#!/usr/bin/env python3
import hashlib,json,os,time
from pathlib import Path
import numpy as np, torch
R=Path(__file__).resolve().parent; REPO=R.parents[1]
def sha(p):
 h=hashlib.sha256()
 with open(p,'rb') as f:
  for b in iter(lambda:f.read(8<<20),b''):h.update(b)
 return h.hexdigest()
def dump(p,x):p.write_text(json.dumps(x,indent=2,sort_keys=True,default=lambda v:v.item() if isinstance(v,np.generic) else str(v))+'\n')
d=json.loads((R/'decision.json').read_text()); assert d['terminal_outcome']=='planoracle_prospective_discovery_passed'
# Post-decision synchronized MPS gate+decision microbenchmark; statistical verdict is already immutable.
with np.load(R/'data/prospective_evaluated.npz') as z,np.load(R/'freeze/gate_contract.npz') as c,np.load(R/'freeze/gate_weights.npz') as w:
 x=np.c_[z['features'].reshape(-1,1046)[:1024],np.tile(np.eye(3),(len(z['target']),1))[:1024]];mean=c['feature_mean'];std=c['feature_std'];wr=w['wr'];ww=w['ww']
device=torch.device('mps');xt=torch.tensor(x,dtype=torch.float32,device=device);mt=torch.tensor(mean,dtype=torch.float32,device=device);st=torch.tensor(std,dtype=torch.float32,device=device);rt=torch.tensor(wr,dtype=torch.float32,device=device);wt=torch.tensor(ww,dtype=torch.float32,device=device)
def run():
 q=(xt-mt)/st;return torch.minimum(q@rt,q@wt)
for _ in range(10):run();torch.mps.synchronize()
vals=[]
for _ in range(50):
 t=time.perf_counter();run();torch.mps.synchronize();vals.append((time.perf_counter()-t)*1000)
lat={'post_decision_only':True,'device':'mps','rows':1024,'operation':'selected sealed gate normalization + dual-linear score (model latency not remeasured)','median_ms':float(np.median(vals)),'p05_ms':float(np.quantile(vals,.05)),'p95_ms':float(np.quantile(vals,.95)),'excluded_from_decision':True};dump(R/'metrics/latency.json',lat)
ledger=json.loads((R/'cohort_seed_ledger.json').read_text());sets={k:{x['episode_id'] for x in v} for k,v in ledger['roles'].items() if k!='replacement'};pairs={f'{a}_{b}':sorted(sets[a]&sets[b]) for i,a in enumerate(sets) for b in list(sets)[i+1:]};audit={'passed':all(not v for v in pairs.values()),'pairwise_episode_id_intersections':pairs,'prior_numeric_overlap':ledger['overlap_with_prior_recorded_identifiers'],'counts':{k:len(v) for k,v in sets.items()}};dump(R/'audit/disjointness_final.json',audit)
c=d['criteria'];report=f'''# PlanOracle-native adaptive-computation discovery report\n\n## Verdict\n\n`{d['terminal_outcome']}`. The frozen causal, contact-free minimax dual-linear gate passed every preregistered prospective criterion at exact total-FLOP parity. This authorizes only a future, entirely fresh V5 confirmation task; V5 was not launched.\n\n## Facts\n\n- Prospective cohort: 180 fresh PlanOracle episodes, 6,840 transitions; mean model calls {d['compute']['mean_calls']:.6f}; fully counted adaptive FLOPs {d['compute']['adaptive_total_flops']:,}.\n- Raw benefit vs analytic exact-FLOP mixture: {c['raw_vs_analytic']['estimate']:.8g}, 95% CI [{c['raw_vs_analytic']['lower']:.8g}, {c['raw_vs_analytic']['upper']:.8g}].\n- Raw benefit vs conservative seeded mixture: {c['raw_vs_seeded']['estimate']:.8g}, CI [{c['raw_vs_seeded']['lower']:.8g}, {c['raw_vs_seeded']['upper']:.8g}].\n- Raw benefit vs fixed depth 1: {c['raw_vs_fixed_d1']['estimate']:.8g}, CI [{c['raw_vs_fixed_d1']['lower']:.8g}, {c['raw_vs_fixed_d1']['upper']:.8g}].\n- Raw benefit vs call-histogram randomization: {c['raw_vs_histogram']['estimate']:.8g}, CI [{c['raw_vs_histogram']['lower']:.8g}, {c['raw_vs_histogram']['upper']:.8g}].\n- Native-whitened benefit vs analytic mixture: {c['white_vs_analytic']['estimate']:.8g}, CI [{c['white_vs_analytic']['lower']:.8g}, {c['white_vs_analytic']['upper']:.8g}].\n- Native-whitened benefit vs histogram randomization: {c['white_vs_histogram']['estimate']:.8g}, CI [{c['white_vs_histogram']['lower']:.8g}, {c['white_vs_histogram']['upper']:.8g}].\n- Stagewise score/gain Spearman correlations: {', '.join(f"stage {x['stage']}={x['rho']:.4f}" for x in d['stagewise_rank'])}; every sign is positive.\n- Conservative comparator used {d['compute']['seeded_total_flops']:,} FLOPs, weakly more than adaptive by {d['compute']['seeded_total_flops']-d['compute']['adaptive_total_flops']:,}. All hash, disjointness, causal/contact exclusion, gradient isolation, exact-call, sparse/dense, histogram, parity, nondominance, and stagewise-sign audits passed.\n\n## Assumptions and interpretation\n\nThe declared PlanOracle implementation and deterministic reset amendment define the DGP; this study does not claim reconstruction of or distribution matching to the released corpus. The result supports prospective discovery that causal allocation improves both coordinate systems under this declared DGP. LoopWM remains relevant prior adaptive-computation work; no “first adaptive world model” claim is made.\n\n## Limitations\n\nThis is discovery, not confirmation. Whitening was estimated from 120 fit episodes and is DGP-specific. The gate search was deliberately compact. NumPy/Accelerate emitted spurious overflow warnings on finite matrix products; independent recomputation reproduced exact finite scores, calls, and headline effects. Post-decision latency covers the sealed gate path only, not a fresh end-to-end base/refiner benchmark, and is excluded from the verdict. Contact was not used and no contact-aware conclusion follows.\n\n## Decision mapping\n\nAll four raw CI lower bounds, both native-whitened CI lower bounds, nondominance, integrity, and positive stagewise signs passed; therefore the immutable mapping yields `{d['terminal_outcome']}`.\n''';(R/'REPORT.md').write_text(report)
# Complete manifest is created last and excludes itself and its verification record.
files=[p for p in R.rglob('*') if p.is_file() and p.name not in ('artifact_manifest.json','artifact_manifest_verification.json') and '__pycache__' not in p.parts];manifest={'schema_version':1,'file_count':len(files),'files':{str(p.relative_to(REPO)):sha(p) for p in sorted(files)},'terminal_outcome':d['terminal_outcome'],'v5_launched':False};dump(R/'artifact_manifest.json',manifest);mh=sha(R/'artifact_manifest.json');verify=all(sha(REPO/p)==h for p,h in manifest['files'].items());dump(R/'audit/artifact_manifest_verification.json',{'passed':verify,'manifest_sha256':mh,'file_count':len(files)});print(json.dumps({'outcome':d['terminal_outcome'],'manifest_sha256':mh,'files':len(files),'latency':lat},sort_keys=True))
